<?php namespace Workspace; ?>
<p class="lede">Журнал успешных изменений. Содержимое договоров, секреты, суммы и коды приглашений в журнал не записываются.</p>
<form method="get" class="filters"><input type="hidden" name="p" value="audit"><label>Проект<select name="project"><option value="">Все доступные события</option><?php selectOptions($projects,$selected) ?></select></label><button class="secondary">Применить</button></form>
<section class="panel"><div class="panelhead"><h2>События аудита</h2></div><?php if (!$events): ?><p class="empty">Нет событий.</p><?php else: ?><div class="tablewrap"><table><thead><tr><th>Дата UTC</th><th>Исполнитель</th><th>Проект</th><th>Событие</th><th>Объект</th></tr></thead><tbody><?php foreach ($events as $e): ?><tr><td><?= h($e['created_at']) ?></td><td><?= h($e['actor_name']) ?></td><td><?= h($e['project_title']??'Организация') ?></td><td><?= h($e['event']) ?><small><?= h($e['detail']) ?></small></td><td>#<?= h($e['object_id']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?><?php if ($nextBefore): ?><div class="pager"><a href="<?= h(url('audit',array_filter(['project'=>$selected,'before'=>$nextBefore]))) ?>">Следующая страница</a></div><?php endif ?></section>
